_PRICE_RE = re.compile(r"[0-9]+(\.[0-9]{1,2})?")
_DIGITS_RE = re.compile(r"[0-9]+")
_QUANTITY_RE = re.compile(r"[+-]?[0-9]+")
_DATE_RE = re.compile(r"([0-9]{4})-([0-9]{2})-([0-9]{2})")
_ORDER_ID_RE = re.compile(r"[Ss][Oo]-[0-9]+")
_MOVEMENT_RE = re.compile(
    r"[ \t]*([^ \t]+)[ \t]+([^ \t]+)[ \t]+([^ \t]+)(.*)", re.DOTALL
)
_FIELD_SPLIT_RE = re.compile(r"[ \t]+")
_MIN_PRICE = Decimal("0.01")


def iter_lines(text):
    """Yield ``(line_number, line)`` for every line that carries data."""
    if text.startswith("﻿"):
        text = text[1:]
    segments = text.split("\n")
    last = len(segments)
    for number, raw in enumerate(segments, 1):
        # CRLF ends a line; a CR with no LF after it (end of file) is content
        if number < last and raw.endswith("\r"):
            raw = raw[:-1]
        body = raw.strip(WS)
        if not body or body.startswith("#"):
            continue
        yield number, raw


def parse_date(text):
    """Return a ``datetime.date`` for ``YYYY-MM-DD`` text, else ``None``."""
    match = _DATE_RE.fullmatch(text)
    if not match:
        return None
    try:
        return date(int(match.group(1)), int(match.group(2)), int(match.group(3)))
    except ValueError:
        return None


def _whole_number(number, text, what):
    try:
        return int(text)
    except ValueError:  # absurdly long digit strings
        raise ParseError(number, "%s %r is too large" % (what, text[:20]))


def _sku(number, text, catalog):
    if not _SKU_RE.fullmatch(text) or text.upper() not in catalog:
        raise ParseError(number, "unknown SKU %r" % text)
    return text.upper()


def _date(number, text):
    day = parse_date(text)
    if day is None:
        raise ParseError(number, "bad date %r (want a real YYYY-MM-DD date)" % text)
    return day


def parse_catalog(text):
    """Parse catalog.txt text into a dict of SKU -> :class:`Product`."""
    catalog = {}
    first_seen = {}
    for number, raw in iter_lines(text):
        fields = [field.strip(WS) for field in raw.split("|")]
        if len(fields) not in (4, 5):
            raise ParseError(
                number,
                "expected 4 or 5 fields separated by '|', found %d" % len(fields),
            )
        sku_text, name, price_text, reorder_text = fields[:4]
        tax = fields[4].lower() if len(fields) == 5 else "standard"
        if not _SKU_RE.fullmatch(sku_text):
            raise ParseError(number, "bad SKU %r (want letters-digits like AB-100)" % sku_text)
        sku = sku_text.upper()
        if sku in catalog:
            raise ParseError(
                number, "duplicate SKU %s (first on line %d)" % (sku, first_seen[sku])
            )
        if not name:
            raise ParseError(number, "name is empty")
